import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.BZohXCq9.js";const h=JSON.parse('{"title":"Admin Dashboard -> Help & Support (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/help-support.md","filePath":"modules/admin-dashboard/help-support.md"}'),l={name:"modules/admin-dashboard/help-support.md"};function i(c,e,s,r,n,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="admin-dashboard-help-support-deep" tabindex="-1">Admin Dashboard -&gt; Help &amp; Support (deep) <a class="header-anchor" href="#admin-dashboard-help-support-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Help &amp; Support (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>help-support</code><br><strong>Route:</strong> <code>/admin-dashboard/help-support</code></p><p>This module lets a super admin manage FAQs and the support contact email used by the platform.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Maintain the FAQ list shown in the platform.</li><li>Maintain the support email/contact details.</li><li>Keep FAQ and support settings under admin control.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/HelpSupport.tsx</code></td><td>Main route page</td><td>Provides the two-tab shell: <code>FAQ</code> and <code>Contact Details</code>; reads <code>user.id</code> from <code>useAuth()</code> and passes it into <code>FaqTab</code>.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/FaqTab.tsx</code></td><td>FAQ section shell</td><td>Opens <code>FaqForm</code> and renders <code>FaqList</code>.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/FaqForm.tsx</code></td><td>Create FAQ dialog</td><td>Calls <code>CREATE_FAQ</code>; refetches <code>GET_FAQS_BY_ADMIN</code>.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/FaqList.tsx</code></td><td>FAQ list and edit/delete UI</td><td>Calls <code>GET_FAQS_BY_ADMIN</code>, <code>UPDATE_FAQ</code>, <code>DELETE_FAQ</code>.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/ContactDetails.tsx</code></td><td>Support-email management UI</td><td>Calls <code>GET_MY_CONTACT_DETAIL</code>, <code>CREATE_CONTACT_DETAIL</code>, <code>UPDATE_CONTACT_DETAIL</code>.</td></tr><tr><td><code>Frontend/src/graphql/Queries/Faqs.ts</code></td><td>FAQ queries</td><td>Defines <code>GET_ALL_FAQS</code>, <code>GET_FAQS_BY_ADMIN</code>, <code>GET_FAQ_BY_ID</code>.</td></tr><tr><td><code>Frontend/src/graphql/mutations/Faqs.ts</code></td><td>FAQ mutations</td><td>Defines <code>CREATE_FAQ</code>, <code>UPDATE_FAQ</code>, <code>DELETE_FAQ</code>.</td></tr><tr><td><code>Frontend/src/graphql/Queries/AdminContact.ts</code></td><td>Contact queries</td><td>Defines <code>GET_MY_CONTACT_DETAIL</code> and <code>GET_ALL_CONTACT_DETAILS</code>.</td></tr><tr><td><code>Frontend/src/graphql/mutations/AdminContact.ts</code></td><td>Contact mutations</td><td>Defines <code>CREATE_CONTACT_DETAIL</code>, <code>UPDATE_CONTACT_DETAIL</code>, <code>DELETE_CONTACT_DETAIL</code>, <code>SEND_CONTACT_EMAIL</code>.</td></tr></tbody></table><h2 id="frontend-graphql-used-by-this-module" tabindex="-1">Frontend GraphQL used by this module <a class="header-anchor" href="#frontend-graphql-used-by-this-module" aria-label="Permalink to &quot;Frontend GraphQL used by this module&quot;">​</a></h2><h3 id="faq-tab" tabindex="-1">FAQ tab <a class="header-anchor" href="#faq-tab" aria-label="Permalink to &quot;FAQ tab&quot;">​</a></h3><ul><li><code>GET_FAQS_BY_ADMIN</code><ul><li>Used by <code>FaqList.tsx</code></li></ul></li><li><code>CREATE_FAQ</code><ul><li>Used by <code>FaqForm.tsx</code></li></ul></li><li><code>UPDATE_FAQ</code><ul><li>Used by <code>FaqList.tsx</code></li></ul></li><li><code>DELETE_FAQ</code><ul><li>Used by <code>FaqList.tsx</code></li></ul></li></ul><h3 id="contact-details-tab" tabindex="-1">Contact Details tab <a class="header-anchor" href="#contact-details-tab" aria-label="Permalink to &quot;Contact Details tab&quot;">​</a></h3><ul><li><code>GET_MY_CONTACT_DETAIL</code><ul><li>Used by <code>ContactDetails.tsx</code></li></ul></li><li><code>CREATE_CONTACT_DETAIL</code><ul><li>Used when no contact record exists yet</li></ul></li><li><code>UPDATE_CONTACT_DETAIL</code><ul><li>Used when the admin edits the existing support email</li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="faq-typedefs-and-resolvers" tabindex="-1">FAQ typeDefs and resolvers <a class="header-anchor" href="#faq-typedefs-and-resolvers" aria-label="Permalink to &quot;FAQ typeDefs and resolvers&quot;">​</a></h3><ul><li>TypeDefs file: <code>server/src/graphql/typeDefs/Faq&#39;sTypes.js</code><ul><li>Type: <code>Faq</code></li><li>Query fields: <ul><li><code>getAllFaqs</code></li><li><code>getFaqsByAdmin(adminId: ID!)</code></li><li><code>getFaqById(id: ID!)</code></li></ul></li><li>Mutation fields: <ul><li><code>createFaq(question: String!, answer: String!, adminId: ID!): Faq</code></li><li><code>updateFaq(id: ID!, question: String, answer: String): Faq</code></li><li><code>deleteFaq(id: ID!): Faq</code></li></ul></li></ul></li><li>Resolver file: <code>server/src/graphql/resolvers/Faqs.resolver.js</code><ul><li><code>getFaqsByAdmin</code><ul><li>Admin-only</li><li>Uses authenticated <code>user.id</code></li></ul></li><li><code>createFaq</code><ul><li>Admin-only</li><li>Uses authenticated <code>user.id</code></li><li>If the same question already exists for this admin, updates it instead of creating a duplicate</li></ul></li><li><code>updateFaq</code><ul><li>Admin-only</li></ul></li><li><code>deleteFaq</code><ul><li>Admin-only</li></ul></li></ul></li></ul><h3 id="contact-typedefs-and-resolvers" tabindex="-1">Contact typeDefs and resolvers <a class="header-anchor" href="#contact-typedefs-and-resolvers" aria-label="Permalink to &quot;Contact typeDefs and resolvers&quot;">​</a></h3><ul><li>TypeDefs file: <code>server/src/graphql/typeDefs/AdminContactTypes.js</code><ul><li>Types: <ul><li><code>ContactDetail</code></li><li><code>ContactInput</code></li><li><code>ContactResponse</code></li></ul></li><li>Query fields: <ul><li><code>getAllContactDetails</code></li><li><code>getMyContactDetail</code></li></ul></li><li>Mutation fields: <ul><li><code>createContactDetail</code></li><li><code>updateContactDetail</code></li><li><code>deleteContactDetail</code></li><li><code>sendContactEmail</code></li></ul></li></ul></li><li>Resolver file: <code>server/src/graphql/resolvers/ContactDetail.resolver.js</code><ul><li><code>getMyContactDetail</code><ul><li>Admin-only</li><li>Reads contact detail by current admin id</li></ul></li><li><code>createContactDetail</code><ul><li>Admin-only</li></ul></li><li><code>updateContactDetail</code><ul><li>Admin-only</li></ul></li><li><code>sendContactEmail</code><ul><li>Validates input</li><li>Reads configured support email</li><li>Sends the contact email through <code>ContaactFormServices</code></li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/services/FaqServices.js</code></td><td>FAQ data access used by FAQ resolvers</td></tr><tr><td><code>server/src/services/ContactAdminServices.js</code></td><td>Contact-detail CRUD used by contact resolvers</td></tr><tr><td><code>server/src/services/ContaactFormServices.js</code></td><td>Sends actual contact email to configured support inbox</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Super admin opens <code>HelpSupport.tsx</code>.</li><li>Tab 1 renders <code>FaqTab</code>: <ul><li><code>FaqList</code> loads <code>GET_FAQS_BY_ADMIN</code></li><li><code>FaqForm</code> creates with <code>CREATE_FAQ</code></li><li>edit/delete actions use <code>UPDATE_FAQ</code> and <code>DELETE_FAQ</code></li></ul></li><li>Tab 2 renders <code>ContactDetails</code>: <ul><li>loads <code>GET_MY_CONTACT_DETAIL</code></li><li>creates or updates support email with <code>CREATE_CONTACT_DETAIL</code> / <code>UPDATE_CONTACT_DETAIL</code></li></ul></li><li>Backend stores FAQ data and contact data through dedicated services.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The route is wrapped in a super-admin gate at the router level, so not every admin sees it.</li><li><code>adminId</code> is still passed from frontend into some FAQ operations for typing/compatibility, but the backend resolver primarily trusts the authenticated <code>user.id</code>.</li><li>FAQ and contact management are separate backend modules even though they share one admin page.</li></ul>',23)])])}const m=t(l,[["render",i]]);export{h as __pageData,m as default};
